def solve_magic(n):
    # Backtracking search
    # x_0 + x_1 + ... + x_{n-1} = n
    # sum(i * x_i) = n

    # Optimization:
    # x_0 = n - (number of non-zero elements)
    # sum(x_i) = n
    # sum(i * x_i) = n

    # Let's use a simple backtracking with pruning
    seq = [0] * n

    def backtrack(idx, current_sum, current_weighted_sum):
        if idx == n:
            if current_sum == n and current_weighted_sum == n:
                # Verify the magic property
                if is_magic(seq):
                    return True
            return False

        # Pruning:
        # Remaining sum needed: n - current_sum
        # Remaining weighted sum needed: n - current_weighted_sum

        # Try values for seq[idx]
        # The maximum possible value for any x_i is n
        for val in range(n - current_sum + 1):
            seq[idx] = val
            new_sum = current_sum + val
            new_weighted_sum = current_weighted_sum + idx * val

            if new_sum <= n and new_weighted_sum <= n:
                if backtrack(idx + 1, new_sum, new_weighted_sum):
                    return True
        return False

    if backtrack(0, 0, 0):
        return seq
    return None

print(solve_magic(15))

